{"content":"// Independent oracle: verify each manifest entry with node:crypto (OpenSSL RSA_PKCS1_PADDING).
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const APP = "/testbed/docsig-verify";
const S = path.join(APP, "samples");
const manifest = JSON.parse(fs.readFileSync(path.join(S, "manifest.json"), "utf8"));

for (const e of manifest.entries) {
  const pub = fs.readFileSync(path.join(S, e.pubkey));
  const bodyRaw = fs.readFileSync(path.join(S, e.doc));
  const bodyUtf8 = Buffer.from(bodyRaw.toString("utf8"), "utf8");
  const sig = Buffer.from(fs.readFileSync(path.join(S, e.sig), "utf8").trim(), "base64");
  const same = bodyRaw.equals(bodyUtf8);
  let v = false;
  try {
    v = crypto.verify("sha256", bodyRaw, { key: pub, padding: crypto.constants.RSA_PKCS1_PADDING }, sig);
  } catch (err) {
    console.log("ERR", e.id, err.message);
  }
  const padInfo = sig.length > 11 ? [sig[0], sig[1], sig[2], sig[3]] : [];
  console.log(`${v ? "VALID  " : "INVALID"}  ${e.id}  e=${e.exponent}  sigLen=${sig.length}  rawBytes==utf8:${same}  padHead=${padInfo.join(",")}`);
}
","filePath":"/tmp/opencode/oracle.js"}

